`default_nettype none
`timescale 1ns/1ps

// Fixed-identity ARP, IPv4, and UDP protocol shell for a 64-bit Ethernet
// payload interface.  ARP replies are generated by udp_complete_64; matching
// UDP traffic is handled by rfudp_eth_app (9000 RF, 9002 echo, 9001 telemetry).
module udp_arp_ethernet_shell_64 #(
    parameter [47:0] LOCAL_MAC = 48'h024741000002,
    parameter [31:0] LOCAL_IP = 32'hC0A82A02,
    parameter [15:0] LOCAL_UDP_PORT = 16'd9000,
    parameter [31:0] STATIC_ARP_IP = 32'd0,
    parameter [47:0] STATIC_ARP_MAC = 48'd0
) (
    input tri0 biz_path_reset,
    input wire eth_rx_frame_event, eth_rx_error_event,
    output wire [31:0] biz_tx_tdata,
    output wire biz_tx_tvalid,
    input wire biz_tx_tready,
    output wire biz_tx_tlast,
    input wire [7:0] biz_tx_free_blocks,
    input wire [31:0] biz_rx_tdata,
    input wire biz_rx_tvalid,
    output wire biz_rx_tready,
    input wire biz_rx_tlast, biz_rx_block_avail,
    input wire ctrl_biz_tx_enable, ctrl_echo_enable, ctrl_telem_enable,
    input wire [31:0] ctrl_reasm_timeout_us,
    input wire [15:0] ctrl_telem_period_ms,
    input wire ctrl_clear_stats,
    input wire [31:0] telem_tdata,
    input wire telem_tvalid,
    output wire telem_tready,
    input wire telem_tlast,
    input wire [2:0] telem_flags,
    input wire [31:0] eth_status,
    output wire [1183:0] eth_stats_vec,
    output wire [31:0] udp_rx_other_packets,
    input  wire        clk,
    input  wire        rst,
    input  wire        s_eth_hdr_valid,
    output wire        s_eth_hdr_ready,
    input  wire [47:0] s_eth_dest_mac,
    input  wire [47:0] s_eth_src_mac,
    input  wire [15:0] s_eth_type,
    input  wire [63:0] s_eth_payload_tdata,
    input  wire [7:0]  s_eth_payload_tkeep,
    input  wire        s_eth_payload_tvalid,
    output wire        s_eth_payload_tready,
    input  wire        s_eth_payload_tlast,
    input  wire        s_eth_payload_tuser,
    output wire        m_eth_hdr_valid,
    input  wire        m_eth_hdr_ready,
    output wire [47:0] m_eth_dest_mac,
    output wire [47:0] m_eth_src_mac,
    output wire [15:0] m_eth_type,
    output wire [63:0] m_eth_payload_tdata,
    output wire [7:0]  m_eth_payload_tkeep,
    output wire        m_eth_payload_tvalid,
    input  wire        m_eth_payload_tready,
    output wire        m_eth_payload_tlast,
    output wire        m_eth_payload_tuser
);

    wire        udp_rx_hdr_valid;
    wire        udp_rx_hdr_ready;
    wire [31:0] udp_rx_source_ip;
    wire [31:0] udp_rx_dest_ip;
    wire [15:0] udp_rx_source_port;
    wire [15:0] udp_rx_dest_port;
    wire [15:0] udp_rx_length;
    wire [15:0] udp_rx_checksum;
    wire [63:0] udp_rx_data;
    wire [7:0]  udp_rx_keep;
    wire        udp_rx_valid;
    wire        udp_rx_ready;
    wire        udp_rx_last;
    wire        udp_rx_user;

    wire        udp_tx_hdr_valid;
    wire        udp_tx_hdr_ready;
    wire [31:0] udp_tx_source_ip;
    wire [31:0] udp_tx_dest_ip;
    wire [15:0] udp_tx_source_port;
    wire [15:0] udp_tx_dest_port;
    wire [15:0] udp_tx_length;
    wire [15:0] udp_tx_checksum;
    wire [63:0] udp_tx_data;
    wire [7:0]  udp_tx_keep;
    wire        udp_tx_valid;
    wire        udp_tx_ready;
    wire        udp_tx_last;
    wire        udp_tx_user;

    wire [3:0] ip_rx_errors;
    wire [1:0] udp_rx_errors;
    wire [2:0] tx_errors;
    rfudp_eth_app #(.LOCAL_IP(LOCAL_IP)) u_rfudp_eth_app (
        .biz_tx_tdata(biz_tx_tdata),
        .biz_tx_tvalid(biz_tx_tvalid),
        .biz_tx_tready(biz_tx_tready),
        .biz_tx_tlast(biz_tx_tlast),
        .biz_tx_free_blocks(biz_tx_free_blocks),
        .biz_rx_tdata(biz_rx_tdata),
        .biz_rx_tvalid(biz_rx_tvalid),
        .biz_rx_tready(biz_rx_tready),
        .biz_rx_tlast(biz_rx_tlast),
        .biz_rx_block_avail(biz_rx_block_avail),
        .biz_path_reset(biz_path_reset),.ctrl_biz_tx_enable(ctrl_biz_tx_enable),
        .ctrl_echo_enable(ctrl_echo_enable),
        .ctrl_telem_enable(ctrl_telem_enable),
        .ctrl_reasm_timeout_us(ctrl_reasm_timeout_us),
        .ctrl_telem_period_ms(ctrl_telem_period_ms),
        .ctrl_clear_stats(ctrl_clear_stats),
        .telem_tdata(telem_tdata),
        .telem_tvalid(telem_tvalid),
        .telem_tready(telem_tready),
        .telem_tlast(telem_tlast),
        .telem_flags(telem_flags),
        .eth_status(eth_status),
        .eth_stats_vec(eth_stats_vec),
        .udp_rx_other_packets(udp_rx_other_packets),
        .eth_rx_event(eth_rx_frame_event), .eth_bad_event(eth_rx_error_event),
        .arp_rx_event(s_eth_hdr_valid && s_eth_hdr_ready && s_eth_type==16'h0806),
        .arp_tx_event(m_eth_hdr_valid && m_eth_hdr_ready && m_eth_type==16'h0806),
        .rx_error_event(|ip_rx_errors || |udp_rx_errors), .tx_error_event(|tx_errors),
        .clk           (clk),
        .rst           (rst),
        .s_hdr_valid   (udp_rx_hdr_valid),
        .s_hdr_ready   (udp_rx_hdr_ready),
        .s_source_ip   (udp_rx_source_ip),
        .s_dest_ip     (udp_rx_dest_ip),
        .s_source_port (udp_rx_source_port),
        .s_dest_port   (udp_rx_dest_port),
        .s_length      (udp_rx_length),
        .s_checksum    (udp_rx_checksum),
        .m_hdr_valid   (udp_tx_hdr_valid),
        .m_hdr_ready   (udp_tx_hdr_ready),
        .m_source_ip   (udp_tx_source_ip),
        .m_dest_ip     (udp_tx_dest_ip),
        .m_source_port (udp_tx_source_port),
        .m_dest_port   (udp_tx_dest_port),
        .m_length      (udp_tx_length),
        .m_checksum    (udp_tx_checksum),
        .s_data        (udp_rx_data),
        .s_keep        (udp_rx_keep),
        .s_valid       (udp_rx_valid),
        .s_ready       (udp_rx_ready),
        .s_last        (udp_rx_last),
        .s_user        (udp_rx_user),
        .m_data        (udp_tx_data),
        .m_keep        (udp_tx_keep),
        .m_valid       (udp_tx_valid),
        .m_ready       (udp_tx_ready),
        .m_last        (udp_tx_last),
        .m_user        (udp_tx_user)
    );

    udp_complete_64 #(
        .STATIC_ARP_IP  (STATIC_ARP_IP),
        .STATIC_ARP_MAC (STATIC_ARP_MAC)
    ) u_udp_complete (
        .clk                         (clk),
        .rst                         (rst),
        .s_eth_hdr_valid             (s_eth_hdr_valid),
        .s_eth_hdr_ready             (s_eth_hdr_ready),
        .s_eth_dest_mac              (s_eth_dest_mac),
        .s_eth_src_mac               (s_eth_src_mac),
        .s_eth_type                  (s_eth_type),
        .s_eth_payload_axis_tdata    (s_eth_payload_tdata),
        .s_eth_payload_axis_tkeep    (s_eth_payload_tkeep),
        .s_eth_payload_axis_tvalid   (s_eth_payload_tvalid),
        .s_eth_payload_axis_tready   (s_eth_payload_tready),
        .s_eth_payload_axis_tlast    (s_eth_payload_tlast),
        .s_eth_payload_axis_tuser    (s_eth_payload_tuser),
        .m_eth_hdr_valid             (m_eth_hdr_valid),
        .m_eth_hdr_ready             (m_eth_hdr_ready),
        .m_eth_dest_mac              (m_eth_dest_mac),
        .m_eth_src_mac               (m_eth_src_mac),
        .m_eth_type                  (m_eth_type),
        .m_eth_payload_axis_tdata    (m_eth_payload_tdata),
        .m_eth_payload_axis_tkeep    (m_eth_payload_tkeep),
        .m_eth_payload_axis_tvalid   (m_eth_payload_tvalid),
        .m_eth_payload_axis_tready   (m_eth_payload_tready),
        .m_eth_payload_axis_tlast    (m_eth_payload_tlast),
        .m_eth_payload_axis_tuser    (m_eth_payload_tuser),
        .local_mac                   (LOCAL_MAC),
        .local_ip                    (LOCAL_IP),
        .gateway_ip                  (32'd0),
        .subnet_mask                 (32'hffffff00),
        .clear_arp_cache             (1'b0),
        .s_udp_hdr_valid             (udp_tx_hdr_valid),
        .s_udp_hdr_ready             (udp_tx_hdr_ready),
        .s_udp_ip_dscp               (6'd0),
        .s_udp_ip_ecn                (2'd0),
        .s_udp_ip_ttl                (8'd64),
        .s_udp_ip_source_ip          (udp_tx_source_ip),
        .s_udp_ip_dest_ip            (udp_tx_dest_ip),
        .s_udp_source_port           (udp_tx_source_port),
        .s_udp_dest_port             (udp_tx_dest_port),
        .s_udp_length                (udp_tx_length),
        .s_udp_checksum              (udp_tx_checksum),
        .s_udp_payload_axis_tdata    (udp_tx_data),
        .s_udp_payload_axis_tkeep    (udp_tx_keep),
        .s_udp_payload_axis_tvalid   (udp_tx_valid),
        .s_udp_payload_axis_tready   (udp_tx_ready),
        .s_udp_payload_axis_tlast    (udp_tx_last),
        .s_udp_payload_axis_tuser    (udp_tx_user),
        .m_udp_hdr_valid             (udp_rx_hdr_valid),
        .m_udp_hdr_ready             (udp_rx_hdr_ready),
        .m_udp_ip_dscp               (),
        .m_udp_ip_ecn                (),
        .m_udp_ip_ttl                (),
        .m_udp_ip_source_ip          (udp_rx_source_ip),
        .m_udp_ip_dest_ip            (udp_rx_dest_ip),
        .m_udp_source_port           (udp_rx_source_port),
        .m_udp_dest_port             (udp_rx_dest_port),
        .m_udp_length                (udp_rx_length),
        .m_udp_checksum              (udp_rx_checksum),
        .m_udp_payload_axis_tdata    (udp_rx_data),
        .m_udp_payload_axis_tkeep    (udp_rx_keep),
        .m_udp_payload_axis_tvalid   (udp_rx_valid),
        .m_udp_payload_axis_tready   (udp_rx_ready),
        .m_udp_payload_axis_tlast    (udp_rx_last),
        .m_udp_payload_axis_tuser    (udp_rx_user),
        .s_ip_hdr_valid              (1'b0),
        .m_ip_hdr_ready              (1'b1),
        .m_ip_payload_axis_tready    (1'b1),
        .ip_rx_error_header_early_termination(ip_rx_errors[0]),
        .ip_rx_error_payload_early_termination(ip_rx_errors[1]),
        .ip_rx_error_invalid_header(ip_rx_errors[2]),
        .ip_rx_error_invalid_checksum(ip_rx_errors[3]),
        .udp_rx_error_header_early_termination(udp_rx_errors[0]),
        .udp_rx_error_payload_early_termination(udp_rx_errors[1]),
        .ip_tx_error_payload_early_termination(tx_errors[0]),
        .ip_tx_error_arp_failed(tx_errors[1]),
        .udp_tx_error_payload_early_termination(tx_errors[2])
    );

endmodule

`default_nettype wire
